def with_sleep(func):
    """Decorator: Add sleep before function call"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        time.sleep(1)
        return func(*args, **kwargs)
    return wrapper

# Apply decorator
sai_thrift_get_acl_counter_attribute = with_sleep(sai_thrift_get_acl_counter_attribute_original)

def hex_to_ascii(h):
    hexstr = hex(h)
    return hexstr_to_ascii(hexstr[2:])

def ifa2_udp_packet(pktlen=82, eth_dst='00:01:02:03:04:05', eth_src='00:06:07:08:09:0a',
                    dl_vlan_enable=False, vlan_pcp=0, vlan_vid=0,
                    ip_src='192.168.0.1', ip_dst='192.168.0.2', ip_dscp=None, ip_ecn=None, ip_ttl=64,
                    udp_sport=1234, udp_dport=80, ip_proto=253,
                    request_vector=0x3f, hop_limit=5, max_length=42, current_length=7,
                    metadata='eeeeeeee1111111122222222333333334444444455555555ffffffff'):

    ifa_header = chr(0x2f) + chr(0x11) + chr(0x00) + chr(max_length)
    metadata_header = chr(request_vector) + chr(0x00) + chr(hop_limit) + chr(current_length)
    udp_hdr = packet.UDP(sport=udp_sport, dport=udp_dport, chksum=0)
    ip_tos = ip_make_tos(0, ip_ecn, ip_dscp)

    if (dl_vlan_enable):
        pkt = packet.Ether(dst=eth_dst, src=eth_src) / packet.Dot1Q(prio=vlan_pcp, vlan=vlan_vid) / \
              packet.IP(src=ip_src, dst=ip_dst, tos=ip_tos, ttl=ip_ttl, proto=ip_proto) / ifa_header / \
              udp_hdr / metadata_header / hexstr_to_ascii(metadata).encode('latin1')
    else:
        pkt = packet.Ether(dst=eth_dst, src=eth_src) / \
              packet.IP(src=ip_src, dst=ip_dst, tos=ip_tos, ttl=ip_ttl, proto=ip_proto) / ifa_header / \
              udp_hdr / metadata_header / hexstr_to_ascii(metadata).encode('latin1')

    pkt = pkt/(chr(0) * (pktlen - len(pkt)))
    return pkt

def ifa2_udpv6_packet(pktlen=82, eth_dst='00:01:02:03:04:05', eth_src='00:06:07:08:09:0a',
                      dl_vlan_enable=False, vlan_pcp=0, vlan_vid=0, ipv6_dscp=None, ipv6_ecn=None, ip_ttl=64,
                      ip_src='2001:db8:85a3::8a2e:370:7334', ip_dst='2001:db8:85a3::8a2e:370:7335',
                      udp_sport=1234, udp_dport=80, ip_proto=253,
                      request_vector=0x3f, hop_limit=5, max_length=42, current_length=7,
                      metadata='eeeeeeee1111111122222222333333334444444455555555ffffffff'):

    ifa_header = chr(0x2f) + chr(0x11) + chr(0x00) + chr(max_length)
    metadata_header = chr(request_vector) + chr(0x00) + chr(hop_limit) + chr(current_length)
    udp_hdr = packet.UDP(sport=udp_sport, dport=udp_dport, chksum=0)
    ipv6_tc = ip_make_tos(0, ipv6_ecn, ipv6_dscp)
    if (dl_vlan_enable):
        pkt = packet.Ether(dst=eth_dst, src=eth_src) / packet.Dot1Q(prio=vlan_pcp, vlan=vlan_vid) / \
              packet.IPv6(src=ip_src, dst=ip_dst, tc=ipv6_tc, hlim=ip_ttl) / ifa_header / \
              udp_hdr / metadata_header / hexstr_to_ascii(metadata).encode('latin1')
    else:
        pkt = packet.Ether(dst=eth_dst, src=eth_src) / \
              packet.IPv6(src=ip_src, dst=ip_dst, tc=ipv6_tc, nh=ip_proto, hlim=ip_ttl) / ifa_header / \
              udp_hdr / metadata_header / hexstr_to_ascii(metadata).encode('latin1')

    pkt = pkt/(chr(0) * (pktlen - len(pkt)))
    return pkt

QOS_TYPE_DICT = {
    SAI_QOS_MAP_TYPE_DSCP_TO_TC: (
        "dscp", "tc"),
    SAI_QOS_MAP_TYPE_DSCP_TO_COLOR: (
        "dscp", "color"),
    SAI_QOS_MAP_TYPE_TC_TO_QUEUE: (
        "tc", "queue_index"),
    SAI_QOS_MAP_TYPE_DOT1P_TO_COLOR: (
        "dot1p", "color"),
    SAI_QOS_MAP_TYPE_DOT1P_TO_TC: (
        "dot1p", "tc"),
    SAI_QOS_MAP_TYPE_PFC_PRIORITY_TO_QUEUE: (
        "prio", "queue_index"),
    SAI_QOS_MAP_TYPE_PFC_PRIORITY_TO_PRIORITY_GROUP: (
        "prio", "pg"),
    SAI_QOS_MAP_TYPE_TC_TO_PRIORITY_GROUP: (
        "tc", "pg"),
    SAI_QOS_MAP_TYPE_TC_AND_COLOR_TO_DOT1P: (
        "tc", "dot1p", "color"),
    SAI_QOS_MAP_TYPE_TC_AND_COLOR_TO_DSCP: (
        "tc", "dscp", "color")}

def create_inc_ip_list(base_ip, count):
    # Convert base IP to integer
    def ip_to_int(ip_str):
        return struct.unpack("!I",
            socket.inet_aton(ip_str))[0]
    # Convert integer back to IP string
    def int_to_ip(ip_int):
        return socket.inet_ntoa(struct.pack("!I", ip_int))
    base_ip_int = ip_to_int(base_ip)
    ip_list = []
    for i in range(count):
        # Calculate the integer form of the current IP (base IP + index)
        current_ip_int = base_ip_int + i
        ip_list.append(int_to_ip(current_ip_int))
    return ip_list

def create_inc_ipv6_list(base_ipv6, count):
    # Convert base IPv6 to integer
    if isinstance(base_ipv6, str):
        base_ipv6 = ipaddress.IPv6Address(base_ipv6)
    ipv6_list = []
    for i in range(count):
        # Calculate the integer form of the current IPv6 (base IPv6 + index)
        current_ipv6 = base_ipv6 + i
        ipv6_list.append(str(current_ipv6))
    return ipv6_list

def create_and_verify_qos_map(client, map_type, key_list, data_list,
                              verify=True):
    ''' creates and verifies the qos map object with
        the provided key and data value lists
    Args:
        client (client): RPC client
        map_type (uint): qos map type
        key_list (list): qos map key list
        data_list (list): qos map data list
        verify (bool): verify request if True
    Returns:
        obj_id: created object id or 0 if failed to create or verify
    '''
    if len(key_list) != len(data_list):
        print("WARNING length of both lists should be equal")
        return 0
    qos_map_list = create_qos_map_to_value_list(map_type, key_list,
                                                data_list)
    qos_map_id = sai_thrift_create_qos_map(client,
                                           type=int(map_type),
                                           map_to_value_list=qos_map_list)
    if (qos_map_id != 0) and verify:
        if verify_qos_map(client, qos_map_id, map_type, key_list,
                          data_list) is False:
            print("WARNING! failed to verify the qos_map 0x%x" % (qos_map_id))
            sai_thrift_remove_qos_map(client, qos_map_id)
            qos_map_id = 0
    return qos_map_id

def create_qos_map_to_value_list(map_type, key_list, data_list):
    ''' Creates the qos map value list
    Args:
        map_type (uint): qos map type
        key_list (list): qos map key list
        data_list (list): qos map data list
    Returns:
        list: qos map value list
    '''
    map_list = []
    i = 0
    if len(key_list) != len(data_list):
        print("WARNING length of both lists should be equal")
        return 0
    for qos_type_dict_key in QOS_TYPE_DICT:
        if ((map_type == qos_type_dict_key) and
                (len(QOS_TYPE_DICT[qos_type_dict_key]) == 2)):
            for key_list_data in key_list:
                value_list_data = data_list[i]
                mapping = sai_thrift_qos_map_t(
                    key=sai_thrift_qos_map_params_t(
                        **{QOS_TYPE_DICT[qos_type_dict_key][0]:
                           key_list_data}),
                    value=sai_thrift_qos_map_params_t(
                        **{QOS_TYPE_DICT[qos_type_dict_key][1]:
                           value_list_data}))
                map_list.append(mapping)
                i += 1
        elif ((map_type == qos_type_dict_key) and
              (len(QOS_TYPE_DICT[qos_type_dict_key]) == 3)):
            for key_list_data1, key_list_data2 in key_list:
                value_list_data = data_list[i]
                mapping = sai_thrift_qos_map_t(
                    key=sai_thrift_qos_map_params_t(
                        **{QOS_TYPE_DICT[qos_type_dict_key][0]:
                           key_list_data1,
                           QOS_TYPE_DICT[qos_type_dict_key][2]:
                           key_list_data2}),
                    value=sai_thrift_qos_map_params_t(
                        **{QOS_TYPE_DICT[qos_type_dict_key][1]:
                           value_list_data}))
                map_list.append(mapping)
                i += 1
    qos_map_list = sai_thrift_qos_map_list_t(count=len(map_list),
                                             maplist=map_list)
    return qos_map_list

def verify_qos_map(client, qosmap_id, qos_type, key_list, data_list):
    ''' Function verifies the HW QosMap type and map_to_value_list
    Args:
        client (client): client
        qosmap_id (obj_id): qos map object id
        qos_type (uint): qos map type
        key_list (list): qos map key list
        data_list (list): qos map data list
    Returns:
        bool: True if succesfully verified
    '''
    result = True
    attr = sai_thrift_get_qos_map_attribute(
        client,
        qosmap_id,
        type=qos_type,
        map_to_value_list=sai_thrift_qos_map_list_t(
            count=100,
            maplist=[]))

    if attr['type'] != qos_type:
        print("WARNING unexpected qos_map_type=%d, expected %d"
              % (attr['type'].count, qos_type))
        return False
    if len(key_list) != attr['map_to_value_list'].count:
        print(
            "WARNING unexpected map_to_value_list.count=%d, expected %d"
            % (attr['map_to_value_list'].count, len(key_list)))
        return False

    expected_key = QOS_TYPE_DICT[qos_type][0]
    expected_value = QOS_TYPE_DICT[qos_type][1]

    if len(QOS_TYPE_DICT[qos_type]) == 3:
        expected_key2 = QOS_TYPE_DICT[qos_type][2]

    for i, data in enumerate(attr['map_to_value_list'].maplist):
        key_dict = {"color": data.key.color,
                    "dscp": data.key.dscp,
                    "dot1p": data.key.dot1p,
                    "prio": data.key.prio,
                    "tc": data.key.tc}
        value_dict = {"color": data.value.color,
                      "dscp": data.value.dscp,
                      "dot1p": data.value.dot1p,
                      "pg": data.value.pg,
                      "prio": data.value.prio,
                      "tc": data.value.tc,
                      "queue_index": data.value.queue_index}
        if len(QOS_TYPE_DICT[qos_type]) == 2:
            if ((key_dict[expected_key] != key_list[i]) or
                    (value_dict[expected_value] != data_list[i])):
                result = False
                break
        elif len(QOS_TYPE_DICT[qos_type]) == 3:
            if ((key_dict[expected_key] != key_list[i][0]) or
                    (key_dict[expected_key2] != key_list[i][1]) or
                    (value_dict[expected_value] != data_list[i])):
                result = False
                break
        else:
            print("WARNING!!! - UNSUPPORTED qos type")
            result = False
            break
    return result

def random_execute_all_funcs(funcs):
    '''
    After shuffling the order of the func list, execute all sub-funcs
    :param funcs: The list of funcs to be executed
    '''

    if not funcs:
        print("The func list is empty and cannot be executed")
        return
    #Copy the func list to avoid modifying the original list
    shuffled_funcs = funcs.copy()
    #Shuffle the order of funcs
    random.shuffle(shuffled_funcs)
    #Execute the shuffled funcs in sequence
    for func in shuffled_funcs:
        print("fun is %s"%func)
        func()

@group("draft")
class AclTableTypeTestIgr(SaiHelper):
    '''
    ACL Type class. This test creates tables and add entry to full specification
    '''

    def setUp(self):
        '''
        Init and config resources for ACL table testing
        '''
        super(AclTableTypeTestIgr, self).setUp()
        #Set the num of ACL entries to be create
        self.table_entry_number = 512
        #create an ACL table group for ingress stage
        self.table_stage = SAI_ACL_STAGE_INGRESS
        self.table_bind_points = [SAI_ACL_BIND_POINT_TYPE_PORT,
                                  SAI_ACL_BIND_POINT_TYPE_SWITCH,
                                  SAI_ACL_BIND_POINT_TYPE_LAG]
        self.table_bind_point_type_list = sai_thrift_s32_list_t(
            count=len(self.table_bind_points), int32list=self.table_bind_points)
        self.group_type = SAI_ACL_TABLE_GROUP_TYPE_PARALLEL
        self.acl_table_group_Igr = sai_thrift_create_acl_table_group(self.client, self.table_stage, self.table_bind_point_type_list, self.group_type)
        assert(self.acl_table_group_Igr != SAI_NULL_OBJECT_ID)

        #Set the pri for table in the ingress acl group
        self.L3Igr_group_member_priority = 100
        self.MirrorV4_group_member_priority = 100
        self.MirrorV6_group_member_priority = 100
        self.L3V6Igr_group_member_priority = 100
        self.INT_group_member_priority = 100
        self.IsolateV4_group_member_priority = 100
        self.IsolateV6_group_member_priority = 100
        self.Aggstat_group_member_priority = 100

        #create ip list for key set in acl entries
        self.ip_addr1 = '10.0.0.1'
        self.dst_ip_mask = '255.255.255.255'
        self.ip_list1 = create_inc_ip_list(self.ip_addr1, self.table_entry_number)

        self.ip_addr2 = '20.0.0.1'
        self.src_ip_mask = '255.255.255.255'
        self.ip_list2 = create_inc_ip_list(self.ip_addr2, self.table_entry_number)
        #create ipv6 list for key set in acl entries
        self.ipv6_addr1 = '2001:db8::1'
        self.dst_ipv6_mask = 'FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF'
        self.ipv6_list1 = create_inc_ipv6_list(self.ipv6_addr1, self.table_entry_number)
        #config packet action drop for action set in acl entries
        self.packet_action_drop = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_DROP))

        #config mirror action for action set in acl entries
        self.mirror_type = SAI_MIRROR_SESSION_TYPE_LOCAL
        self.mirror_session = sai_thrift_create_mirror_session(
            self.client,
            monitor_port=self.port_list[0],
            type=self.mirror_type)
        self.mirror_session_list = sai_thrift_object_list_t(
            count=1, idlist=[self.mirror_session])
        self.mirror_action = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                objlist=self.mirror_session_list))

        #config tam_int action for action set in acl entries
        self.device_id = 0x78
        self.pb1 = 0xAA
        self.pb2 = 0xBB
        if get_platform() == 'clx':
            self.int_oid = sai_thrift_create_tam_int(self.client, type=SAI_TAM_INT_TYPE_IFA2,
                                                    name_space_id=0xf, device_id=self.device_id, inline=False,
                                                    int_presence_type=SAI_TAM_INT_PRESENCE_TYPE_L3_PROTOCOL,
                                                    int_presence_l3_protocol=0x43)
        else:
            self.int_oid = sai_thrift_create_tam_int(self.client, type=SAI_TAM_INT_TYPE_IFA1, device_id=self.device_id,
                                                    inline=False, int_presence_type=SAI_TAM_INT_PRESENCE_TYPE_PB,
                                                    int_presence_pb1=self.pb1, int_presence_pb2=self.pb2)
        self.tam_int_action = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                oid=self.int_oid))

    def runTest(self):
        '''
        Execute the main test logic
        '''

        #This makes the ACLs in the group take effect for traffic entering these ports
        for port in self.port_list:
            status = sai_thrift_set_port_attribute(
                self.client, port, ingress_acl=self.acl_table_group_Igr)
            assert (status == SAI_STATUS_SUCCESS)

        funcs_add = [self.testL3TableAclIgrAdd,
                     self.testMirrorV4TableAclIgrAdd,
                     self.testMirrorV6TableAclIgrAdd,
                     self.testL3V6TableAclIgrAdd,
                     self.testINTTableAclIgrAdd,
                     self.testIsolateV4TableAclIgrAdd,
                     self.testIsolateV6TableAclIgrAdd,
                     self.testAggstatTableAclIgrAdd]
        #Call the func to shuffle the order and execute all sub-funcs
        random_execute_all_funcs(funcs_add)

    def tearDown(self):
        '''
        Clean up resources after testing
        '''

        #Remove the ACL binding from ports to revert to original state
        funcs_rm = [self.testL3TableAclIgrRm,
                    self.testMirrorV4TableAclIgrRm,
                    self.testMirrorV6TableAclIgrRm,
                    self.testL3V6TableAclIgrRm,
                    self.testINTTableAclIgrRm,
                    self.testIsolateV4TableAclIgrRm,
                    self.testIsolateV6TableAclIgrRm,
                    self.testAggstatTableAclIgrRm]

        for port in self.port_list:
            status = sai_thrift_set_port_attribute(
                self.client, port, ingress_acl=0)
            assert (status == SAI_STATUS_SUCCESS)
        #Call the func to shuffle the order and execute all sub-funcs
        random_execute_all_funcs(funcs_rm)

        #mirror session remove
        sai_thrift_remove_mirror_session(self.client, self.mirror_session)
        #tam int remove
        sai_thrift_remove_tam_int(self.client,self.int_oid)
        #acl table group remove
        status = sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Igr)
        assert (status == SAI_STATUS_SUCCESS)

        super(AclTableTypeTestIgr, self).tearDown()

    def testL3TableAclIgrAdd(self):
        '''
        Verify L3 table ingress creation
        '''
        print("testL3TableAclIgrAdd")
        #Define the types of actions that the ACL table can perform
        self.L3Igr_table_action_types = [SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                         SAI_ACL_ACTION_TYPE_REDIRECT,
                                         SAI_ACL_ACTION_TYPE_COUNTER,
                                         SAI_ACL_ACTION_TYPE_SET_TC,
                                         SAI_ACL_ACTION_TYPE_SET_DSCP]
        if get_platform() == 'clx':
            self.L3Igr_table_action_types.remove(SAI_ACL_ACTION_TYPE_SET_DSCP)
        self.L3Igr_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(self.L3Igr_table_action_types), int32list=self.L3Igr_table_action_types)
        #Create ACL table for ingress traffic
        self.L3Igr_acl_table = sai_thrift_create_acl_table(
            self.client,
            acl_stage=self.table_stage,
            acl_bind_point_type_list=self.table_bind_point_type_list,
            acl_action_type_list=self.L3Igr_table_acl_action_type_list,
            size=self.table_entry_number,
            field_ip_protocol=True,
            field_acl_ip_type=True,
            field_src_ip=True,
            field_dst_ip=True,
            field_l4_src_port=True,
            field_l4_dst_port=True,
            field_dscp=True,
            field_ecn=True,
            field_tcp_flags=True,
            field_acl_ip_frag=True,
            field_outer_vlan_id=True,
            field_in_ports=True)
        assert(self.L3Igr_acl_table != SAI_NULL_OBJECT_ID)
        #Create L3Igr_acl_table as ACL table group member
        self.L3Igr_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            self.L3Igr_acl_table,
            self.L3Igr_group_member_priority)
        #Create ACL counter for ingress traffic
        self.L3Igr_acl_counter_ingress = sai_thrift_create_acl_counter(
            self.client,
            table_id=self.L3Igr_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        self.L3Igr_action_counter_ingress = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=self.L3Igr_acl_counter_ingress),
            enable=True)
        # create acl entry for ACL L3 table
        self.L3Igr_acl_entries_list = []
        for i in range(self.table_entry_number):
            self.dst_ip_t = sai_thrift_acl_field_data_t(
                enable=True,
                data=sai_thrift_acl_field_data_data_t(ip4=self.ip_list1[i]),
                mask=sai_thrift_acl_field_data_mask_t(ip4=self.dst_ip_mask))
            L3Igr_acl_entry = sai_thrift_create_acl_entry(
                self.client,
                table_id=self.L3Igr_acl_table,
                priority=10 + i,
                field_dst_ip=self.dst_ip_t,
                action_packet_action=self.packet_action_drop)
            sai_thrift_set_acl_entry_attribute(
                self.client, L3Igr_acl_entry,
                action_counter=self.L3Igr_action_counter_ingress)
            self.L3Igr_acl_entries_list.append(L3Igr_acl_entry)

    def testMirrorV4TableAclIgrAdd(self):
        '''
        Verify MirrorV4 table ingress creation
        '''
        print("testMirrorV4TableAclIgrAdd")
        #Define the types of actions that the ACL table can perform
        self.MirrorV4_table_action_types = [SAI_ACL_ACTION_TYPE_COUNTER,
                                            SAI_ACL_ACTION_TYPE_MIRROR_INGRESS]
        self.MirrorV4_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(self.MirrorV4_table_action_types), int32list=self.MirrorV4_table_action_types)
