        self.ip_addr1 = '10.0.0.1'
        self.ip_addr2 = '10.10.10.2'
        self.BTH = hexstr_to_ascii('1140FFFF000042000042C5FF')
        self.BTH1 = hexstr_to_ascii('0440FFFF0000420080C0F84F')
