    def testQsetEcnIgr(self):
        '''
        Verify pkt hit ingress acl with ecn key field
        '''
        print("testQsetEcnIgr")

        #Define the types of actions that the ACL table can perform
        L3Igr_table_action_types = [SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                    SAI_ACL_ACTION_TYPE_REDIRECT,
                                    SAI_ACL_ACTION_TYPE_COUNTER,
                                    SAI_ACL_ACTION_TYPE_SET_TC,
                                    SAI_ACL_ACTION_TYPE_SET_DSCP]
        if get_platform() == 'clx':
            L3Igr_table_action_types.remove(SAI_ACL_ACTION_TYPE_SET_DSCP)
        L3Igr_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(L3Igr_table_action_types), int32list=L3Igr_table_action_types)
        #Create ACL table for ingress traffic
        L3Igr_acl_table = sai_thrift_create_acl_table(
            self.client,
            acl_stage=self.table_stage_Igr,
            acl_bind_point_type_list=self.table_bind_point_type_list,
            acl_action_type_list=L3Igr_table_acl_action_type_list,
            size=self.table_entry_number,
            field_ip_protocol=True,
            field_acl_ip_type=True,
            field_src_ip=True,
            field_dst_ip=True,
            field_l4_src_port=True,
            field_l4_dst_port=True,
            field_dscp=True,
            field_ecn=True,
            field_tcp_flags=True,
            field_acl_ip_frag=True,
            field_outer_vlan_id=True,
            field_in_ports=True)
        assert(L3Igr_acl_table != SAI_NULL_OBJECT_ID)
        #Create L3Igr_acl_table as ACL table group member
        L3Igr_group_member_priority = 100
        L3Igr_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            L3Igr_acl_table,
            L3Igr_group_member_priority)
        #Create ACL counter for ingress traffic
        L3Igr_acl_counter_ingress = sai_thrift_create_acl_counter(
            self.client,
            table_id=L3Igr_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        L3Igr_action_counter_ingress = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=L3Igr_acl_counter_ingress),
            enable=True)
        # create acl entry for ACL L3 table
        field_ecn_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=1),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        dst_ip_mask = '255.255.255.255'
        dst_ip_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(ip4=self.ip_addr1),
            mask=sai_thrift_acl_field_data_mask_t(ip4=dst_ip_mask))

        #config packet action drop for action set in acl entries
        packet_action_drop = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_DROP))

        L3Igr_acl_entry = sai_thrift_create_acl_entry(
            self.client,
            table_id=L3Igr_acl_table,
            priority=10,
            field_ecn=field_ecn_t,
            field_dst_ip=dst_ip_t,
            action_packet_action=packet_action_drop)

        sai_thrift_set_acl_entry_attribute(
            self.client, L3Igr_acl_entry,
            action_counter=L3Igr_action_counter_ingress)

        #This makes the ACLs in the group take effect for traffic entering these ports
        for port in self.port_list:
            status = sai_thrift_set_port_attribute(
                self.client, port, ingress_acl=self.acl_table_group_Igr)
            assert (status == SAI_STATUS_SUCCESS)

        try:
            pkt1 = simple_tcp_packet(eth_dst=ROUTER_MAC,
                                     eth_src=self.src_mac,
                                     ip_dst=self.ip_addr1,
                                     tcp_dport=self.l4_dst_port,
                                     ip_id=105,
                                     ip_ttl=64,
                                     ip_tos=201)
            exp_pkt1 = simple_tcp_packet(eth_dst=self.dst_mac,
                                         eth_src=ROUTER_MAC,
                                         ip_dst=self.ip_addr1,
                                         tcp_dport=self.l4_dst_port,
                                         ip_id=105,
                                         ip_ttl=63,
                                         ip_tos=201)

            pkt2 = simple_tcp_packet(eth_dst=ROUTER_MAC,
                                     eth_src=self.src_mac,
                                     ip_dst=self.ip_addr1,
                                     tcp_dport=self.l4_dst_port,
                                     ip_id=105,
                                     ip_ttl=64,
                                     ip_tos=200)
            exp_pkt2 = simple_tcp_packet(eth_dst=self.dst_mac,
                                         eth_src=ROUTER_MAC,
                                         ip_dst=self.ip_addr1,
                                         tcp_dport=self.l4_dst_port,
                                         ip_id=105,
                                         ip_ttl=63,
                                         ip_tos=200)

            # verify packet dropped after ACL apply, ecn 01 hit acl kset and drop
            send_packet(self, self.dev_port0, pkt1)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)
            # ecn 00 can not hit acl kset
            send_packet(self, self.dev_port0, pkt2)
            verify_packet(self, exp_pkt2, self.dev_port1)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)

            field_ecn1_t = sai_thrift_acl_field_data_t(
                enable=True,
                data=sai_thrift_acl_field_data_data_t(u8=0),
                mask=sai_thrift_acl_field_data_mask_t(u8=-1))

            sai_thrift_set_acl_entry_attribute(
                self.client, L3Igr_acl_entry,
                field_ecn=field_ecn1_t)

           # verify packet dropped after ACL apply, ecn 01 can not hit acl kset
            send_packet(self, self.dev_port0, pkt1)
            verify_packet(self, exp_pkt1, self.dev_port1)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)
            # ecn 00 hit acl kset and drop
            send_packet(self, self.dev_port0, pkt2)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 2)

        finally:
            #Remove the ACL binding from ports to revert to original state
            status = sai_thrift_remove_acl_table_group_member(self.client, L3Igr_acl_table_group_member)
            assert (status == SAI_STATUS_SUCCESS)
            action_counter_ingress_rm = sai_thrift_acl_action_data_t(
                parameter=sai_thrift_acl_action_parameter_t(
                    oid=0),
                enable=True)
            #remove ACL entry
            sai_thrift_set_acl_entry_attribute(
                self.client, L3Igr_acl_entry,
                action_counter=action_counter_ingress_rm)
            status = sai_thrift_remove_acl_entry(self.client, L3Igr_acl_entry)
            assert (status == SAI_STATUS_SUCCESS)
            #Set attr for the ACL counter to reset packet counts
            sai_thrift_set_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=0)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 0)
            #Remove ACL counter
            sai_thrift_remove_acl_counter(self.client, L3Igr_acl_counter_ingress)
            for port in self.port_list:
                status = sai_thrift_set_port_attribute(
                    self.client, port, ingress_acl=0)
                assert (status == SAI_STATUS_SUCCESS)

            #Remove L3 ingress ACL table
            status = sai_thrift_remove_acl_table(self.client, L3Igr_acl_table)
            assert (status == SAI_STATUS_SUCCESS)

