@group("draft")
class AclQsetIptypeTest(SaiHelperSimplified):
    """
    Verify matching on ip type field
    """

    def setUp(self):
        super(AclQsetIptypeTest, self).setUp()
        self.dst_mac = '00:11:22:33:44:55'
        self.src_mac = '00:22:22:22:22:22'
        self.ip_addr1 = '10.0.0.1'
        self.ip_addr2 = '10.10.10.2'
        self.ip_addr3 = '10.10.10.3'
        self.ip_addr4 = '20.0.0.1'
        self.ipv6_addr1 = '1234:5678:9abc:def0:4422:1133:5577:99aa'
        self.ipv6_addr2 = '1234:5678:9abc:def0:4422:1133:5577:99ab'
        self.l4_dst_port = 1000
        self.l4_src_port = 2000

        self.port0_rif = sai_thrift_create_router_interface(
            self.client,
            type=SAI_ROUTER_INTERFACE_TYPE_PORT,
            virtual_router_id=self.default_vrf,
            port_id=self.port0)

        self.port1_rif = sai_thrift_create_router_interface(
            self.client,
            type=SAI_ROUTER_INTERFACE_TYPE_PORT,
            virtual_router_id=self.default_vrf,
            port_id=self.port1)

        self.port2_rif = sai_thrift_create_router_interface(
            self.client,
            type=SAI_ROUTER_INTERFACE_TYPE_PORT,
            virtual_router_id=self.default_vrf,
            port_id=self.port2)

        self.nhop1 = sai_thrift_create_next_hop(
            self.client,
            ip=sai_ipaddress(self.ip_addr2),
            router_interface_id=self.port1_rif,
            type=SAI_NEXT_HOP_TYPE_IP)
        self.neighbor_entry1 = sai_thrift_neighbor_entry_t(
            rif_id=self.port1_rif, ip_address=sai_ipaddress(self.ip_addr2))
        sai_thrift_create_neighbor_entry(
            self.client, self.neighbor_entry1, dst_mac_address=self.dst_mac)

        self.nhop2 = sai_thrift_create_next_hop(
            self.client,
            ip=sai_ipaddress(self.ip_addr3),
            router_interface_id=self.port2_rif,
            type=SAI_NEXT_HOP_TYPE_IP)
        self.neighbor_entry2 = sai_thrift_neighbor_entry_t(
            rif_id=self.port2_rif, ip_address=sai_ipaddress(self.ip_addr3))
        sai_thrift_create_neighbor_entry(
            self.client, self.neighbor_entry2, dst_mac_address=self.dst_mac)

        self.route_entry0 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf, destination=sai_ipprefix('10.0.0.1/24'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry0, next_hop_id=self.nhop1)

        self.route_entry1 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf,
            destination=sai_ipprefix(
                '1234:5678:9abc:def0:4422:1133:5577:99aa/128'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry1, next_hop_id=self.nhop1)

        self.route_entry2 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf, destination=sai_ipprefix('20.0.0.1/24'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry2, next_hop_id=self.nhop2)

        self.route_entry3 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf,
            destination=sai_ipprefix(
                '1234:5678:9abc:def0:4422:1133:5577:99ab/128'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry3, next_hop_id=self.nhop2)

        #Set the num of ACL entries to be create
        self.table_entry_number = 512

        #create an ACL table group for ingress stage
        self.table_stage_Igr = SAI_ACL_STAGE_INGRESS
        self.table_bind_points = [SAI_ACL_BIND_POINT_TYPE_PORT,
                                  SAI_ACL_BIND_POINT_TYPE_SWITCH]
        self.table_bind_point_type_list = sai_thrift_s32_list_t(
            count=len(self.table_bind_points), int32list=self.table_bind_points)
        self.group_type = SAI_ACL_TABLE_GROUP_TYPE_PARALLEL
        self.acl_table_group_Igr = sai_thrift_create_acl_table_group(self.client, self.table_stage_Igr, self.table_bind_point_type_list, self.group_type)
        assert(self.acl_table_group_Igr != SAI_NULL_OBJECT_ID)

        #create an ACL table group for egress stage
        self.table_stage_Egr = SAI_ACL_STAGE_EGRESS
        self.acl_table_group_Egr = sai_thrift_create_acl_table_group(self.client, self.table_stage_Egr, self.table_bind_point_type_list, self.group_type)
        assert(self.acl_table_group_Egr != SAI_NULL_OBJECT_ID)

    def runTest(self):
        """
        Create acl table and entry for packets hit
        """

        self.testQsetIptypeIgr()
        self.testQsetIptypeEgr()

    def tearDown(self):
        '''
        Clean up resources after testing
        '''
        sai_thrift_remove_route_entry(self.client, self.route_entry0)
        sai_thrift_remove_route_entry(self.client, self.route_entry1)
        sai_thrift_remove_route_entry(self.client, self.route_entry2)
        sai_thrift_remove_route_entry(self.client, self.route_entry3)
        sai_thrift_remove_next_hop(self.client, self.nhop1)
        sai_thrift_remove_next_hop(self.client, self.nhop2)
        sai_thrift_remove_neighbor_entry(self.client, self.neighbor_entry1)
        sai_thrift_remove_neighbor_entry(self.client, self.neighbor_entry2)
        sai_thrift_remove_router_interface(self.client, self.port0_rif)
        sai_thrift_remove_router_interface(self.client, self.port1_rif)
        sai_thrift_remove_router_interface(self.client, self.port2_rif)
        status1 = sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Igr)
        assert (status1 == SAI_STATUS_SUCCESS)
        status2 = sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Egr)
        assert (status2 == SAI_STATUS_SUCCESS)

        super(AclQsetIptypeTest, self).tearDown()

