        #Create L3Igr_acl_table as ACL table group member
        L3Igr_group_member_priority = 100
        L3Igr_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            L3Igr_acl_table,
            L3Igr_group_member_priority)
        #Create ACL counter for ingress traffic
        L3Igr_acl_counter_ingress = sai_thrift_create_acl_counter(
            self.client,
            table_id=L3Igr_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        L3Igr_action_counter_ingress = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=L3Igr_acl_counter_ingress),
            enable=True)
        # create acl entry for ACL L3 table
        ip_type = SAI_ACL_IP_TYPE_IPV4ANY
        ip_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ip_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        #config packet action drop for action set in acl entries
        packet_action_drop = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_DROP))

        L3Igr_acl_entry = sai_thrift_create_acl_entry(
            self.client,
            table_id=L3Igr_acl_table,
            priority=10,
            field_acl_ip_type=ip_type_t,
            action_packet_action=packet_action_drop)

        sai_thrift_set_acl_entry_attribute(
            self.client, L3Igr_acl_entry,
            action_counter=L3Igr_action_counter_ingress)

        #This makes the ACLs in the group take effect for traffic entering these ports
        for port in self.port_list:
            status = sai_thrift_set_port_attribute(
                self.client, port, ingress_acl=self.acl_table_group_Igr)
            assert (status == SAI_STATUS_SUCCESS)

        try:
            pkt1 = simple_tcp_packet(eth_dst=ROUTER_MAC,
                                     eth_src=self.src_mac,
                                     ip_dst=self.ip_addr1,
                                     ip_ttl=64)
            exp_pkt1 = simple_tcp_packet(eth_dst=self.dst_mac,
                                         eth_src=ROUTER_MAC,
                                         ip_dst=self.ip_addr1,
                                         ip_ttl=63)

            pkt2 = simple_tcpv6_packet(
                eth_dst=ROUTER_MAC,
                eth_src=self.src_mac,
                ipv6_dst=self.ipv6_addr1,
                ipv6_hlim=64)
            exp_pkt2 = simple_tcpv6_packet(
                eth_dst=self.dst_mac,
                eth_src=ROUTER_MAC,
                ipv6_dst=self.ipv6_addr1,
                ipv6_hlim=63)

            # verify packet dropped after ACL apply, ipv4 pkt hit acl kset and drop
            send_packet(self, self.dev_port0, pkt1)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)
            # ipv6 pkt can not hit acl kset
            send_packet(self, self.dev_port0, pkt2)
            verify_packet(self, exp_pkt2, self.dev_port1)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)

        finally:
            #Remove the ACL binding from ports to revert to original state
            status = sai_thrift_remove_acl_table_group_member(self.client, L3Igr_acl_table_group_member)
            assert (status == SAI_STATUS_SUCCESS)
            action_counter_ingress_rm = sai_thrift_acl_action_data_t(
                parameter=sai_thrift_acl_action_parameter_t(
                    oid=0),
                enable=True)
            #remove ACL entry
            sai_thrift_set_acl_entry_attribute(
                self.client, L3Igr_acl_entry,
                action_counter=action_counter_ingress_rm)
            status = sai_thrift_remove_acl_entry(self.client, L3Igr_acl_entry)
            assert (status == SAI_STATUS_SUCCESS)
            #Set attr for the ACL counter to reset packet counts
            sai_thrift_set_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=0)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 0)
            #Remove ACL counter
            sai_thrift_remove_acl_counter(self.client, L3Igr_acl_counter_ingress)
            for port in self.port_list:
                status = sai_thrift_set_port_attribute(
                    self.client, port, ingress_acl=0)
                assert (status == SAI_STATUS_SUCCESS)

            #Remove L3 ingress ACL table
            status = sai_thrift_remove_acl_table(self.client, L3Igr_acl_table)
            assert (status == SAI_STATUS_SUCCESS)

