class BindLagsOneTableSameEntry(AclLagBaseTopo):
    """
    Summary: grp bind multi lag,one table,one entry in ports multi lag member
    """
    def setUp(self):
        super(BindLagsOneTableSameEntry, self).setUp()

        #Set the num of ACL entries to be create
        self.table_entry_number = 512

        #create an ACL table group for ingress stage
        self.table_stage = SAI_ACL_STAGE_INGRESS
        self.table_bind_points = [SAI_ACL_BIND_POINT_TYPE_PORT,SAI_ACL_BIND_POINT_TYPE_LAG]
        self.table_bind_point_type_list = sai_thrift_s32_list_t(
            count=len(self.table_bind_points), int32list=self.table_bind_points)
        self.group_bind_points = [SAI_ACL_BIND_POINT_TYPE_LAG, SAI_ACL_BIND_POINT_TYPE_PORT]
        self.group_bind_point_type_list = sai_thrift_s32_list_t(count=len(self.group_bind_points),
        int32list=self.group_bind_points)

        self.group_type = SAI_ACL_TABLE_GROUP_TYPE_PARALLEL
        self.acl_table_group_Igr = sai_thrift_create_acl_table_group(self.client, self.table_stage,
        self.table_bind_point_type_list, self.group_type)
        assert(self.acl_table_group_Igr != SAI_NULL_OBJECT_ID)

    def runTest(self):
        """
        Create acl table and entry for packets hit
        """
        #Define the types of actions that the ACL table can perform
        L3Igr_table_action_types = [SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                    SAI_ACL_ACTION_TYPE_REDIRECT,
                                    SAI_ACL_ACTION_TYPE_COUNTER,
                                    SAI_ACL_ACTION_TYPE_SET_TC,
                                    SAI_ACL_ACTION_TYPE_SET_DSCP]
        if get_platform() == 'clx':
            L3Igr_table_action_types.remove(SAI_ACL_ACTION_TYPE_SET_DSCP)
        L3Igr_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(L3Igr_table_action_types), int32list=L3Igr_table_action_types)
        #Create ACL table for ingress traffic
        L3Igr_acl_table = sai_thrift_create_acl_table(
            self.client,
            acl_stage=self.table_stage,
            acl_bind_point_type_list=self.table_bind_point_type_list,
            acl_action_type_list=L3Igr_table_acl_action_type_list,
            size=self.table_entry_number,
            field_ip_protocol=True,
            field_acl_ip_type=True,
            field_src_ip=True,
            field_dst_ip=True,
            field_l4_src_port=True,
            field_l4_dst_port=True,
            field_dscp=True,
            field_ecn=True,
            field_tcp_flags=True,
            field_acl_ip_frag=True,
            field_outer_vlan_id=True,
            field_in_ports=True)
        assert(L3Igr_acl_table != SAI_NULL_OBJECT_ID)

        #Create L3Igr_acl_table as ACL table group member
        L3Igr_group_member_priority = 100
        L3Igr_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            L3Igr_acl_table,
            L3Igr_group_member_priority)
        #Create ACL counter for ingress traffic
        L3Igr_acl_counter_ingress = sai_thrift_create_acl_counter(
            self.client,
            table_id=L3Igr_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        L3Igr_action_counter_ingress = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=L3Igr_acl_counter_ingress),
            enable=True)

        dst_ip_mask = '255.255.255.0'
        dst_ip_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(ip4=self.dst_ip0),
            mask=sai_thrift_acl_field_data_mask_t(ip4=dst_ip_mask))

        portlist = [self.port24, self.port25]
        portobjlist=sai_thrift_object_list_t(
            count=len(portlist),
            idlist=portlist)
        in_ports_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(objlist=portobjlist),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        ip_type = SAI_ACL_IP_TYPE_IPV4ANY
        ip_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ip_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        ip_pro = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=6),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        #config packet action drop for action set in acl entries
        packet_action_drop = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_DROP))

        packet_action_log = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_LOG))
        L3Igr_acl_entry = sai_thrift_create_acl_entry(
            self.client,
            table_id=L3Igr_acl_table,
            priority=10,
            field_in_ports=in_ports_t,
            field_ip_protocol=ip_pro,
            field_acl_ip_type=ip_type_t,
            field_dst_ip = dst_ip_t,
            action_packet_action=packet_action_drop)

        sai_thrift_set_acl_entry_attribute(
            self.client, L3Igr_acl_entry,
            action_counter=L3Igr_action_counter_ingress)

        #This makes the ACLs in the group take effect for traffic entering these ports
        status = sai_thrift_set_lag_attribute(self.client,
                                        lag_oid=self.lag_ids[self.lag_names[0]],
                                        ingress_acl=self.acl_table_group_Igr)

        assert (status == SAI_STATUS_SUCCESS)

        status = sai_thrift_set_lag_attribute(self.client,
                                        lag_oid=self.lag_ids[self.lag_names[1]],
                                        ingress_acl=self.acl_table_group_Igr)
        assert (status == SAI_STATUS_SUCCESS)

        status = sai_thrift_set_lag_attribute(self.client,
                                        lag_oid=self.lag_ids[self.lag_names[2]],
                                        ingress_acl=self.acl_table_group_Igr)
        assert (status == SAI_STATUS_SUCCESS)

        try:
            pkt = simple_tcp_packet(pktlen=100,
                                     eth_dst=ROUTER_MAC,
                                     eth_src=self.src_mac,
                                     dl_vlan_enable=True,
                                     vlan_vid=100,
                                     ip_dst=self.dst_ip0,
                                     ip_tos=252,
                                     ip_ttl=64)
            exp_pkt = simple_tcp_packet(pktlen=96,
                                         eth_dst=self.dst_mac,
                                         eth_src=ROUTER_MAC,
                                         ip_dst=self.dst_ip0,
                                         ip_tos=252,
                                         ip_ttl=63)

            pkt1 = simple_tcp_packet(pktlen=100,
                                     eth_dst=ROUTER_MAC,
                                     eth_src=self.src_mac,
                                     dl_vlan_enable=True,
                                     vlan_vid=200,
                                     ip_dst=self.dst_ip1,
                                     ip_tos=252,
                                     ip_ttl=64)
            exp_pkt1 = simple_tcp_packet(pktlen=96,
                                         eth_dst=self.dst_mac,
                                         eth_src=ROUTER_MAC,
                                         ip_dst=self.dst_ip1,
                                         ip_tos=252,
                                         ip_ttl=63)

            pkt2 = simple_tcp_packet(pktlen=100,
                                     eth_dst=ROUTER_MAC,
                                     eth_src=self.src_mac,
                                     dl_vlan_enable=True,
                                     vlan_vid=300,
                                     ip_dst=self.dst_ip2,
                                     ip_tos=252,
                                     ip_ttl=64)
            exp_pkt2 = simple_tcp_packet(pktlen=96,
                                         eth_dst=self.dst_mac,
                                         eth_src=ROUTER_MAC,
                                         ip_dst=self.dst_ip2,
                                         ip_tos=252,
                                         ip_ttl=63)

            #send from diff lag vlan if to phy if
            send_packet(self, self.dev_port24, pkt)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)

            send_packet(self, self.dev_port25, pkt1)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 2)

            send_packet(self, self.dev_port26, pkt2)
            verify_packet(self, exp_pkt2, self.dev_port30)

            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 2)

            status = sai_thrift_remove_acl_table_group_member(self.client, L3Igr_acl_table_group_member)
            assert (status == SAI_STATUS_SUCCESS)

            send_packet(self, self.dev_port24, pkt)
            verify_packet(self, exp_pkt, self.dev_port30)
            send_packet(self, self.dev_port25, pkt1)
            verify_packet(self, exp_pkt1, self.dev_port30)
            send_packet(self, self.dev_port26, pkt2)
            verify_packet(self, exp_pkt2, self.dev_port30)

            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 2)

            L3Igr_acl_table_group_member = sai_thrift_create_acl_table_group_member(
                self.client,
                self.acl_table_group_Igr,
                L3Igr_acl_table,
                L3Igr_group_member_priority)

            #send from diff lag vlan if to phy if
            send_packet(self, self.dev_port24, pkt)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 3)

            send_packet(self, self.dev_port25, pkt1)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 4)

            send_packet(self, self.dev_port26, pkt2)
            verify_packet(self, exp_pkt2, self.dev_port30)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 4)

            status = sai_thrift_set_lag_attribute(self.client,
                                            lag_oid=self.lag_ids[self.lag_names[0]],
                                            ingress_acl=0)
            assert (status == SAI_STATUS_SUCCESS)

            send_packet(self, self.dev_port24, pkt)
            verify_packet(self, exp_pkt, self.dev_port30)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 4)

            send_packet(self, self.dev_port25, pkt1)
            verify_no_other_packets(self, timeout=2)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 5)

            send_packet(self, self.dev_port26, pkt2)
            verify_packet(self, exp_pkt2, self.dev_port30)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 5)

        finally:
            #Remove the ACL binding from ports to revert to original state
            status = sai_thrift_remove_acl_table_group_member(self.client, L3Igr_acl_table_group_member)
            assert (status == SAI_STATUS_SUCCESS)
            action_counter_ingress_rm = sai_thrift_acl_action_data_t(
                parameter=sai_thrift_acl_action_parameter_t(oid=0), enable=True)
            #remove ACL entry
            sai_thrift_set_acl_entry_attribute(
                self.client, L3Igr_acl_entry,action_counter=action_counter_ingress_rm)
            status = sai_thrift_remove_acl_entry(self.client, L3Igr_acl_entry)
            assert (status == SAI_STATUS_SUCCESS)
            #Set attr for the ACL counter to reset packet counts
            sai_thrift_set_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=0)
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, L3Igr_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 0)
            #Remove ACL counter
            sai_thrift_remove_acl_counter(self.client, L3Igr_acl_counter_ingress)

            status = sai_thrift_set_lag_attribute(self.client,
                                            lag_oid=self.lag_ids[self.lag_names[0]],
                                            ingress_acl=0)
            assert (status == SAI_STATUS_SUCCESS)
            status = sai_thrift_set_lag_attribute(self.client,
                                            lag_oid=self.lag_ids[self.lag_names[1]],
                                            ingress_acl=0)
            assert (status == SAI_STATUS_SUCCESS)
            status = sai_thrift_set_lag_attribute(self.client,
                                            lag_oid=self.lag_ids[self.lag_names[2]],
                                            ingress_acl=0)
            assert (status == SAI_STATUS_SUCCESS)

            #Remove L3 ingress ACL table
            status = sai_thrift_remove_acl_table(self.client, L3Igr_acl_table)
            assert (status == SAI_STATUS_SUCCESS)

    def tearDown(self):
        '''
        Clean up resources after testing
        '''
        sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Igr)
        super(BindLagsOneTableSameEntry, self).tearDown()

