#ÊÖ¹¤µ÷ÊÔÓÃ
@group("draft")
class AclTableTypeStressTestEgr1(SaiHelperSimplified):

    '''
    ACL Type class. This test creates tables and add entry to full specification
    '''

    def setUp(self):
        '''
        Init and config resources for ACL table testing
        '''
        super(AclTableTypeStressTestEgr1, self).setUp()
        #Set the num of ACL entries to be create
        self.table_entry_number = 256

        #create an ACL table group for egress stage
        self.table_stage = SAI_ACL_STAGE_EGRESS
        self.table_bind_points = [SAI_ACL_BIND_POINT_TYPE_PORT,
                                  SAI_ACL_BIND_POINT_TYPE_SWITCH,
                                  SAI_ACL_BIND_POINT_TYPE_LAG]
        self.table_bind_point_type_list = sai_thrift_s32_list_t(
            count=len(self.table_bind_points), int32list=self.table_bind_points)
        self.group_type = SAI_ACL_TABLE_GROUP_TYPE_PARALLEL
        self.acl_table_group_Egr = sai_thrift_create_acl_table_group(self.client, self.table_stage, self.table_bind_point_type_list, self.group_type)
        assert(self.acl_table_group_Egr != SAI_NULL_OBJECT_ID)

        #Set the pri for table in the egress acl group
        self.L3Egr_group_member_priority = 100
        self.L3V6Egr_group_member_priority = 100
        self.AggstatEgr_group_member_priority = 100

        #create ip list for key set in acl entries
        self.ip_addr1 = '10.0.0.1'
        self.dst_ip_mask = '255.255.255.255'
        self.ip_list1 = create_inc_ip_list(self.ip_addr1, self.table_entry_number)

        self.ip_addr2 = '20.0.0.1'
        self.src_ip_mask = '255.255.255.255'
        self.ip_list2 = create_inc_ip_list(self.ip_addr2, self.table_entry_number)
        #create ipv6 list for key set in acl entries
        self.ipv6_addr1 = '2001:db8::1'
        self.dst_ipv6_mask = 'FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF'
        self.ipv6_list1 = create_inc_ipv6_list(self.ipv6_addr1, self.table_entry_number)

        #config packet action drop for action set in acl entries
        self.packet_action_drop = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_DROP))

        self.vlan100 = sai_thrift_create_vlan(self.client, vlan_id=100)

        self.lag_id = sai_thrift_create_lag(self.client)

        self.lag_member_id1 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id, port_id=self.port7)
        self.lag_member_id2 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id, port_id=self.port8)
        self.lag_member_id3 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id, port_id=self.port9)

        self.lag_id1 = sai_thrift_create_lag(self.client)

        self.lag_member_id4 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id1, port_id=self.port10)
        self.lag_member_id5 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id1, port_id=self.port11)
        self.lag_member_id6 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id1, port_id=self.port12)

        self.lag_bp = sai_thrift_create_bridge_port(
            self.client,
            bridge_id=self.default_1q_bridge,
            port_id=self.lag_id,
            type=SAI_BRIDGE_PORT_TYPE_PORT,
            admin_state=True)
        self.assertNotEqual(self.lag_bp, 0)

        self.lag1_bp = sai_thrift_create_bridge_port(
            self.client,
            bridge_id=self.default_1q_bridge,
            port_id=self.lag_id1,
            type=SAI_BRIDGE_PORT_TYPE_PORT,
            admin_state=True)
        self.assertNotEqual(self.lag1_bp, 0)
        self.vlan100_member0 = sai_thrift_create_vlan_member(
            self.client,
            vlan_id=self.vlan100,
            bridge_port_id=self.lag_bp,
            vlan_tagging_mode=SAI_VLAN_TAGGING_MODE_UNTAGGED)

        self.vlan100_member1 = sai_thrift_create_vlan_member(
            self.client,
            vlan_id=self.vlan100,
            bridge_port_id=self.lag1_bp,
            vlan_tagging_mode=SAI_VLAN_TAGGING_MODE_UNTAGGED)

        # self.port0_bp = sai_thrift_create_bridge_port(
        #     self.client,
        #     bridge_id=self.default_1q_bridge,
        #     port_id=self.port0,
        #     type=SAI_BRIDGE_PORT_TYPE_PORT,
        #     admin_state=True)

        # self.vlan100_member2 = sai_thrift_create_vlan_member(
