@group("draft")
class AclStressTestBaseTopo(SaiHelper):
    '''
    Stess case for acl test
    '''
    def setUp(self):
        super(AclStressTestBaseTopo, self).setUp()

        self.dst_mac = '00:11:22:33:44:55'
        self.src_mac = '00:22:22:22:22:22'
        self.ip_addr1 = '10.0.0.1'
        self.ip_addr2 = '10.10.10.2'
        self.ip_addr3 = '10.10.10.3'
        self.ip_addr4 = '20.0.0.1'
        self.ipv6_addr1 = '1234:5678:9abc:def0:4422:1133:5577:99aa'
        self.ipv6_addr2 = '1234:5678:9abc:def0:4422:1133:5577:99ab'
        self.dst_ipv6_mask = 'FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF'
        self.l4_dst_port = 1000
        self.l4_src_port = 2000

        #´´½¨VLAN
        vlans = [100, 200, 300, 400]
        self.vlan_objs = []
        for vid in vlans:
            vlan_obj = sai_thrift_create_vlan(self.client, vlan_id=vid)
            self.vlan_objs.append(vlan_obj)

        #¶¨ÒåLAG×é¼°¶ÔÓ¦¶Ë¿ÚÁÐ±í
        lag_port_mappings = [
            {"lag_name": "lag_id", "ports":
        [self.port0, self.port1, self.port2, self.port3]},
            {"lag_name": "lag_id1", "ports":
        [self.port12, self.port13, self.port14, self.port15]},
            {"lag_name": "lag_id2", "ports":
        [self.port16, self.port17, self.port18, self.port19]},
            {"lag_name": "lag_id3", "ports":
        [self.port28, self.port29, self.port30, self.port31]},
        ]

        self.lag_ids = {}
        self.lag_member_ids = {}
        for mapping in lag_port_mappings:
            lag_id = sai_thrift_create_lag(self.client)
            self.lag_ids[mapping["lag_name"]] = lag_id
            member_ids = []
            for port in mapping["ports"]:
                member_id = sai_thrift_create_lag_member(self.client, lag_id=lag_id, port_id=port)
                member_ids.append(member_id)
            self.lag_member_ids[mapping["lag_name"]] = member_ids

        lag_names = ["lag_id", "lag_id1", "lag_id2", "lag_id3"]
        self.lag_bps = []

        for lag_name in lag_names:
            bp = sai_thrift_create_bridge_port(
                self.client,
                bridge_id=self.default_1q_bridge,
                port_id=self.lag_ids[lag_name],
                type=SAI_BRIDGE_PORT_TYPE_PORT,
                admin_state=True)
            self.assertNotEqual(bp, 0)
            self.lag_bps.append(bp)

        port_list1 = [self.port4, self.port11, self.port20, self.port27]
        self.phy_bps = []

        for port in port_list1:
            bp1 = sai_thrift_create_bridge_port(
                self.client,
                bridge_id=self.default_1q_bridge,
                port_id=port,
                type=SAI_BRIDGE_PORT_TYPE_PORT,
                admin_state=True)
            self.assertNotEqual(bp1, 0)
            self.phy_bps.append(bp1)

        vlan_configs = [
            {"vlan_idx": 0, "lag_bp_idx": 0, "phy_bp_idx": 0},
            {"vlan_idx": 1, "lag_bp_idx": 1, "phy_bp_idx": 1},
            {"vlan_idx": 2, "lag_bp_idx": 2, "phy_bp_idx": 2},
            {"vlan_idx": 3, "lag_bp_idx": 3, "phy_bp_idx": 3},
        ]

        self.vlan_members_lag = []
        self.vlan_members_phy = []
        self.vlan_rifs = []

        for config in vlan_configs:
            vlan_member_lag = sai_thrift_create_vlan_member(
                self.client,
                vlan_id=self.vlan_objs[config["vlan_idx"]],
                bridge_port_id=self.lag_bps[config["lag_bp_idx"]],
                vlan_tagging_mode=SAI_VLAN_TAGGING_MODE_UNTAGGED)
            self.vlan_members_lag.append(vlan_member_lag)

            vlan_member_phy = sai_thrift_create_vlan_member(
                self.client,
                vlan_id=self.vlan_objs[config["vlan_idx"]],
                bridge_port_id=self.phy_bps[config["phy_bp_idx"]],
                vlan_tagging_mode=SAI_VLAN_TAGGING_MODE_UNTAGGED)
            self.vlan_members_phy.append(vlan_member_phy)

            vlan_rif = sai_thrift_create_router_interface(
                self.client,
                type=SAI_ROUTER_INTERFACE_TYPE_VLAN,
                virtual_router_id=self.default_vrf,
                vlan_id=self.vlan_objs[config["vlan_idx"]])
            self.vlan_rifs.append(vlan_rif)

        port_list2 = [self.port5, self.port6, self.port7, self.port8, self.port9, self.port10]
        self.rif_ids= []

        for port in port_lists:
            rif_id = sai_thrift_create_router_interface(
                self.client,
                type=SAI_ROUTER_INTERFACE_TYPE_PORT,
                virtual_router_id=self.default_vrf,
                port_id=port)
            self.rif_ids.append(rif_id)

        self.nhop1 = sai_thrift_create_next_hop(
            self.client,
            ip=sai_ipaddress(self.ip_addr2),
            router_interface_id=self.rif_id2,
            type=SAI_NEXT_HOP_TYPE_IP)
        self.neighbor_entry1 = sai_thrift_neighbor_entry_t(
            rif_id=self.rif_ids[0], ip_address=sai_ipaddress(self.ip_addr2))
        sai_thrift_create_neighbor_entry(
            self.client, self.neighbor_entry1, dst_mac_address=self.dst_mac)

        self.route_entry0 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf, destination=sai_ipprefix('10.0.0.1/24'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry0, next_hop_id=self.nhop1)

        self.route_entry1 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf,
            destination=sai_ipprefix(
                '1234:5678:9abc:def0:4422:1133:5577:99aa/128'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry1, next_hop_id=self.nhop1)

    def tearDown(self):
        sai_thrift_remove_route_entry(self.client, self.route_entry0)
        sai_thrift_remove_route_entry(self.client, self.route_entry1)
        sai_thrift_remove_next_hop(self.client, self.nhop1)
        sai_thrift_remove_neighbor_entry(self.client, self.neighbor_entry1)

        for rif_id in self.rif_ids:
            sai_thrift_remove_router_interface(self.client, rif_id)
            self.rif_ids.clear()

        for vlan_rif in self.vlan_rifs:
            sai_thrift_remove_router_interface(self.client, vlan_rif)
            self.vlan_rifs.clear()

        for vlan_member_lag in self.vlan_members_lag:
            sai_thrift_remove_router_interface(self.client, vlan_rif)
            self.vlan_members_lag.clear()

        super(AclStressTestBaseTopo, self).tearDown()

