    def testL3TableAclIgrAdd(self):
        '''
        Verify L3 table ingress creation
        '''
        print("testL3TableAclIgrAdd")
        #Define the types of actions that the ACL table can perform
        self.L3Igr_table_action_types = [SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                         SAI_ACL_ACTION_TYPE_REDIRECT,
                                         SAI_ACL_ACTION_TYPE_COUNTER,
                                         SAI_ACL_ACTION_TYPE_SET_TC,
                                         SAI_ACL_ACTION_TYPE_SET_DSCP]
        if get_platform() == 'clx':
            self.L3Igr_table_action_types.remove(SAI_ACL_ACTION_TYPE_SET_DSCP)
        self.L3Igr_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(self.L3Igr_table_action_types), int32list=self.L3Igr_table_action_types)
        #Create ACL table for ingress traffic
        self.L3Igr_acl_table = sai_thrift_create_acl_table(
            self.client,
            acl_stage=self.table_stage,
            acl_bind_point_type_list=self.table_bind_point_type_list,
            acl_action_type_list=self.L3Igr_table_acl_action_type_list,
            size=self.table_entry_number,
            field_ip_protocol=True,
            field_acl_ip_type=True,
            field_src_ip=True,
            field_dst_ip=True,
            field_l4_src_port=True,
            field_l4_dst_port=True,
            field_dscp=True,
            field_ecn=True,
            field_tcp_flags=True,
            field_acl_ip_frag=True,
            field_outer_vlan_id=True,
            field_in_ports=True)
        assert(self.L3Igr_acl_table != SAI_NULL_OBJECT_ID)
        #Create L3Igr_acl_table as ACL table group member
        self.L3Igr_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            self.L3Igr_acl_table,
            self.L3Igr_group_member_priority)
        #Create ACL counter for ingress traffic
        self.L3Igr_acl_counter_ingress_tcp = sai_thrift_create_acl_counter(
            self.client,
            table_id=self.L3Igr_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        self.L3Igr_action_counter_ingress_tcp = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=self.L3Igr_acl_counter_ingress_tcp),
            enable=True)
        #Create ACL counter for ingress traffic
        self.L3Igr_acl_counter_ingress_udp = sai_thrift_create_acl_counter(
            self.client,
            table_id=self.L3Igr_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        self.L3Igr_action_counter_ingress_udp = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=self.L3Igr_acl_counter_ingress_udp),
            enable=True)

        ip_type = SAI_ACL_IP_TYPE_IPV4ANY
        ip_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ip_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        self.ip_protocol_tcp = 6
        self.ip_protocol_udp = 17

        self.field_ip_protocol_tcp = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=self.ip_protocol_tcp),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_ip_protocol_udp = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=self.ip_protocol_udp),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        # create acl entry for ACL L3 table
        self.L3Igr_acl_entry_tcp = sai_thrift_create_acl_entry(
            self.client,
            table_id=self.L3Igr_acl_table,
            priority=10,
            field_acl_ip_type=ip_type_t,
            field_ip_protocol=self.field_ip_protocol_tcp,
            action_packet_action=self.packet_action_drop)

        sai_thrift_set_acl_entry_attribute(
            self.client, self.L3Igr_acl_entry_tcp,
            action_counter=self.L3Igr_action_counter_ingress_tcp)

        self.L3Igr_acl_entry_udp = sai_thrift_create_acl_entry(
            self.client,
            table_id=self.L3Igr_acl_table,
            priority=10,
            field_acl_ip_type=ip_type_t,
            field_ip_protocol=self.field_ip_protocol_udp,
            action_packet_action=self.packet_action_drop)

        sai_thrift_set_acl_entry_attribute(
            self.client, self.L3Igr_acl_entry_udp,
            action_counter=self.L3Igr_action_counter_ingress_udp)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt1)
