    def testAggstatTableAclIgrAdd(self):
        '''
        Verify Aggregate_Stat table ingress creation
        '''
        print("testAggstatTableAclIgrAdd")
        #Define the types of actions that the ACL table can perform
        self.Aggstat_table_action_types = [SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                           SAI_ACL_ACTION_TYPE_SET_DSCP,
                                           SAI_ACL_ACTION_TYPE_PER_PORT_COUNTER,
                                           SAI_ACL_ACTION_TYPE_SET_ACL_META_DATA]
        if get_platform() == 'clx':
            self.Aggstat_table_action_types.remove(SAI_ACL_ACTION_TYPE_SET_DSCP)

        self.Aggstat_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(self.Aggstat_table_action_types), int32list=self.Aggstat_table_action_types)
        self.Aggstat_table_entry_number = 32

        #Create ACL table for ingress traffic
        self.Aggstat_acl_table = sai_thrift_create_acl_table(
            self.client,
            acl_stage=self.table_stage,
            acl_bind_point_type_list=self.table_bind_point_type_list,
            acl_action_type_list=self.Aggstat_table_acl_action_type_list,
            size=self.Aggstat_table_entry_number,
            field_in_ports=True,
            field_dscp=True,
            field_port_group_type=True,
            field_ecn=True,
            field_ip_protocol=True,
            field_acl_ip_type=True,
            field_l4_src_port=True,
            field_l4_dst_port=True)
        assert(self.Aggstat_acl_table != SAI_NULL_OBJECT_ID)

        #Create Aggstat_acl_table as ACL table group member
        self.Aggstat_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            self.Aggstat_acl_table,
            self.Aggstat_group_member_priority)

        # create acl entry for ACL Aggstat table
        ip_type = SAI_ACL_IP_TYPE_IP
        ip_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ip_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        ipv4_type = SAI_ACL_IP_TYPE_IPV4ANY
        ipv4_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ipv4_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        ipv6_type = SAI_ACL_IP_TYPE_IPV6ANY
        ipv6_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ipv6_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        self.ipv6_next_header_tcp = 6
        self.ipv6_next_header_udp = 17

        self.field_ip_protocol_tcp = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=self.ipv6_next_header_tcp),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_ip_protocol_udp = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=self.ipv6_next_header_udp),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_ecn_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=1),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_dscp_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=50),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.Aggstat_acl_entry = sai_thrift_create_acl_entry(
            self.client,
            table_id=self.Aggstat_acl_table,
            priority=10,
            # field_acl_ip_type=ip_type_t,
            #field_ecn=self.field_ecn_t,
            # field_dscp=self.field_dscp_t,
            field_ip_protocol=self.field_ip_protocol_tcp,
            action_packet_action=self.packet_action_drop)

        send_packet(self, self.dev_port0, self.pkt1)
        verify_packet(self, self.exp_pkt1, self.dev_port26)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt2)
        verify_no_other_packets(self, timeout=2)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_no_other_packets(self, timeout=2)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt4)
        verify_packet(self, self.exp_pkt4, self.dev_port26)

        sai_thrift_set_acl_entry_attribute(
            self.client, self.Aggstat_acl_entry,
            field_ip_protocol=self.field_ip_protocol_udp)

        send_packet(self, self.dev_port0, self.pkt1)
        verify_no_other_packets(self, timeout=2)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt2)
        verify_packet(self, self.exp_pkt2, self.dev_port26)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_packet(self, self.exp_pkt3, self.dev_port26)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt4)
        verify_no_other_packets(self, timeout=2)

        # pdb.set_trace()
        sai_thrift_set_acl_entry_attribute(
            self.client, self.Aggstat_acl_entry,
            field_acl_ip_type=ipv4_type_t)

        send_packet(self, self.dev_port0, self.pkt1)
        verify_packet(self, self.exp_pkt1, self.dev_port26)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt2)
        verify_packet(self, self.exp_pkt2, self.dev_port26)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_packet(self, self.exp_pkt3, self.dev_port26)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt4)
        verify_no_other_packets(self, timeout=2)

        # pdb.set_trace()

        sai_thrift_set_acl_entry_attribute(
            self.client, self.Aggstat_acl_entry,
            field_ip_protocol=self.field_ip_protocol_tcp)

        send_packet(self, self.dev_port0, self.pkt1)
        verify_packet(self, self.exp_pkt1, self.dev_port26)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt2)
        verify_packet(self, self.exp_pkt2, self.dev_port26)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_no_other_packets(self, timeout=2)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt4)
        verify_packet(self, self.exp_pkt4, self.dev_port26)
        # pdb.set_trace()

        sai_thrift_set_acl_entry_attribute(
            self.client, self.Aggstat_acl_entry,
            field_acl_ip_type=ipv6_type_t)


        send_packet(self, self.dev_port0, self.pkt1)
        verify_packet(self, self.exp_pkt1, self.dev_port26)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt2)
        verify_no_other_packets(self, timeout=2)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_packet(self, self.exp_pkt3, self.dev_port26)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt4)
        verify_packet(self, self.exp_pkt4, self.dev_port26)

        # pdb.set_trace()
        sai_thrift_set_acl_entry_attribute(
            self.client, self.Aggstat_acl_entry,
            field_ip_protocol=self.field_ip_protocol_udp)

        send_packet(self, self.dev_port0, self.pkt1)
        verify_no_other_packets(self, timeout=2)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt2)
        verify_packet(self, self.exp_pkt2, self.dev_port26)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_packet(self, self.exp_pkt3, self.dev_port26)


        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port16, self.pkt4)
        verify_packet(self, self.exp_pkt4, self.dev_port26)


    def testL3TableAclIgrRm(self):
        '''
        Verify L3 table ingress destroy
        '''
        print("testL3TableAclIgrRm")
        self.action_counter_ingress_rm = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=0),
            enable=True)
        status = sai_thrift_remove_acl_table_group_member(self.client, self.L3Igr_acl_table_group_member)
        assert (status == SAI_STATUS_SUCCESS)

        #remove ACL entry
        sai_thrift_set_acl_entry_attribute(
            self.client, self.L3Igr_acl_entry_tcp,
            action_counter=self.action_counter_ingress_rm)
        status = sai_thrift_remove_acl_entry(self.client, self.L3Igr_acl_entry_tcp)
        assert (status == SAI_STATUS_SUCCESS)

        sai_thrift_set_acl_entry_attribute(
            self.client, self.L3Igr_acl_entry_udp,
            action_counter=self.action_counter_ingress_rm)
        status = sai_thrift_remove_acl_entry(self.client, self.L3Igr_acl_entry_udp)
        assert (status == SAI_STATUS_SUCCESS)

        #Set attr for the ACL counter to reset packet counts
        sai_thrift_set_acl_counter_attribute(
            self.client, self.L3Igr_acl_counter_ingress_tcp, packets=0)
        packets = sai_thrift_get_acl_counter_attribute(
            self.client, self.L3Igr_acl_counter_ingress_tcp, packets=True)
        self.assertEqual(packets['packets'], 0)

        sai_thrift_set_acl_counter_attribute(
            self.client, self.L3Igr_acl_counter_ingress_udp, packets=0)
        packets = sai_thrift_get_acl_counter_attribute(
            self.client, self.L3Igr_acl_counter_ingress_udp, packets=True)
        self.assertEqual(packets['packets'], 0)

        #Remove ACL counter
        status = sai_thrift_remove_acl_counter(self.client, self.L3Igr_acl_counter_ingress_tcp)
        assert (status == SAI_STATUS_SUCCESS)
        status = sai_thrift_remove_acl_counter(self.client, self.L3Igr_acl_counter_ingress_udp)
        assert (status == SAI_STATUS_SUCCESS)
        #Remove L3 ingress ACL table
        status = sai_thrift_remove_acl_table(self.client, self.L3Igr_acl_table)
        assert (status == SAI_STATUS_SUCCESS)

