    def tearDown(self):
        '''
        Clean up resources after testing
        '''
        #Remove the ACL binding from ports to revert to original state
        # for port in self.port_list:
        #     status = sai_thrift_set_port_attribute(
        #         self.client, port, egress_acl=0)
        #     assert (status == SAI_STATUS_SUCCESS)
        self.testMirrorV4TableAclIgrRm()
        self.testL3TableAclEgrRm()
        self.testAggstatTableAclEgrRm()
        self.testL3TableAclIgrRm()
        self.testL3V6TableAclIgrRm()
        self.testL3V6TableAclEgrRm()

        status = sai_thrift_set_lag_attribute(self.client,
                                lag_oid=self.lag3,
                                egress_acl=0)
        status = sai_thrift_set_lag_attribute(self.client,
                                lag_oid=self.lag3,
                                ingress_acl=0)
        sai_thrift_set_port_attribute(self.client, self.port1, egress_acl=0)

        #Call the func to shuffle the order and execute all sub-funcs
        #mirror session remove
        sai_thrift_remove_mirror_session(self.client, self.mirror_session)

        sai_thrift_remove_route_entry(self.client, self.route_entry0)
        sai_thrift_remove_next_hop(self.client, self.nhop1)
        sai_thrift_remove_neighbor_entry(self.client, self.neighbor_entry1)
        sai_thrift_remove_route_entry(self.client, self.route_entry1)
        sai_thrift_remove_next_hop(self.client, self.nhop2)
        sai_thrift_remove_neighbor_entry(self.client, self.neighbor_entry2)
        sai_thrift_remove_router_interface(self.client, self.port0_rif)
        sai_thrift_remove_router_interface(self.client, self.port1_rif)
        sai_thrift_remove_router_interface(self.client, self.port2_rif)
        sai_thrift_remove_router_interface(self.client, self.port3_rif)

        status = sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Igr)
        sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Egr)
        sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Egr1)
        assert (status == SAI_STATUS_SUCCESS)
        super(L3TestCustomissue2, self).tearDown()


    def testL3TableAclEgrRm(self):
        '''
        Verify L3 table egress destroy
        '''
        print("testL3TableAclEgrRm")
        self.action_counter_egress_rm = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=0),
            enable=True)
        #remove ACL entry
        sai_thrift_remove_acl_table_group_member(self.client, self.L3Egr_acl_table_group_member)
        sai_thrift_remove_acl_table_group_member(self.client, self.L3Egr_acl_table_group_member1)
        for i in range(self.table_entry_number):
            sai_thrift_set_acl_entry_attribute(
                self.client, self.L3Egr_acl_entries_list[i],
                action_counter=self.action_counter_egress_rm)
            status = sai_thrift_remove_acl_entry(self.client, self.L3Egr_acl_entries_list[i])
            assert (status == SAI_STATUS_SUCCESS)

        self.L3Egr_acl_entries_list.clear()
        #Set attr for the ACL counter to reset packet counts
        sai_thrift_set_acl_counter_attribute(
            self.client, self.L3Egr_acl_counter_egress, packets=0)
        packets = sai_thrift_get_acl_counter_attribute(
            self.client, self.L3Egr_acl_counter_egress, packets=True)
        self.assertEqual(packets['packets'], 0)
        #Remove ACL counter
        sai_thrift_remove_acl_counter(self.client, self.L3Egr_acl_counter_egress)
        #Remove L3 ingress ACL table
        status = sai_thrift_remove_acl_table(self.client, self.L3Egr_acl_table)
        assert (status == SAI_STATUS_SUCCESS)

