        l4_src_port_mask = 32759
        l4_src_port_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u16=1236),
            mask=sai_thrift_acl_field_data_mask_t(u16=l4_src_port_mask))
        self.dst_ip_mask = '255.255.255.255'
        self.dst_ip_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(ip4=self.ip_addr1),
            mask=sai_thrift_acl_field_data_mask_t(ip4=self.dst_ip_mask))

