        self.assertEqual(packets['packets'], counter_stats_v6)
        packets = sai_thrift_get_acl_counter_attribute(
            self.client, self.INT_acl_counter_ingress_v4, packets=True)
        self.assertEqual(packets['packets'], counter_stats_v4)

        # verify packet forwarding with ACL hit
        send_packet(self, self.dev_port0, self.pkt3)
        verify_no_other_packets(self, timeout=2)
        counter_stats_v4 +=1
        packets = sai_thrift_get_acl_counter_attribute(
            self.client, self.INT_acl_counter_ingress_v6, packets=True)
