@group("draft")
class AclipprotocolipTypeTestIgr(SaiHelperSimplified):
    '''
    ACL Type class. This test creates tables and add entry to full specification
    _bug149284
    int/agg table don't care v4/v6,don't set ip type for entry
    '''

    def setUp(self):
        '''
        Init and config resources for ACL table testing
        '''
        super(AclipprotocolipTypeTestIgr, self).setUp()
        self.dst_mac = '00:11:22:33:44:55'
        self.src_mac = '00:22:22:22:22:22'
        self.ip_addr1 = '10.0.0.1'
        self.ip_addr2 = '10.10.10.2'
        self.ip_addr3 = '10.10.10.3'
        self.ip_addr4 = '20.0.0.1'
        self.ipv6_addr1 = '1234:5678:9abc:def0:4422:1133:5577:99aa'
        self.ipv6_addr2 = '1234:5678:9abc:def0:4422:1133:5577:99ab'
        self.ipv6_addr3 = '2234:5678:9abc:def0:4422:1133:5577:99ab'
        self.dst_ipv6_mask = 'FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF:FFFF'
        self.l4_dst_port = 1000
        self.l4_src_port = 2000
        self.BTH = hexstr_to_ascii('1140FFFF00001FA80049FF3A')
        self.BTH1 = hexstr_to_ascii('0440FFFF0000420081C0F84F')
        self.AETH = hexstr_to_ascii('00000002')
        self.rocev2_rc_ack_payload = self.BTH + self.AETH
        self.pkt_len = 256
        self.src_port = 8100
        self.dst_port = 4791

        self.vlan100 = sai_thrift_create_vlan(self.client, vlan_id=100)

        self.lag_id = sai_thrift_create_lag(self.client)

        self.lag_member_id1 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id, port_id=self.port0)
        self.lag_member_id2 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id, port_id=self.port1)
        self.lag_member_id3 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id, port_id=self.port2)

        self.lag_id1 = sai_thrift_create_lag(self.client)

        self.lag_member_id4 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id1, port_id=self.port14)
        self.lag_member_id5 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id1, port_id=self.port15)
        self.lag_member_id6 = sai_thrift_create_lag_member(
            self.client, lag_id=self.lag_id1, port_id=self.port16)

        self.lag_bp = sai_thrift_create_bridge_port(
            self.client,
            bridge_id=self.default_1q_bridge,
            port_id=self.lag_id,
            type=SAI_BRIDGE_PORT_TYPE_PORT,
            admin_state=True)
        self.assertNotEqual(self.lag_bp, 0)

        self.lag1_bp = sai_thrift_create_bridge_port(
            self.client,
            bridge_id=self.default_1q_bridge,
            port_id=self.lag_id1,
            type=SAI_BRIDGE_PORT_TYPE_PORT,
            admin_state=True)
        self.assertNotEqual(self.lag1_bp, 0)

        self.vlan100_member0 = sai_thrift_create_vlan_member(
            self.client,
            vlan_id=self.vlan100,
            bridge_port_id=self.lag_bp,
            vlan_tagging_mode=SAI_VLAN_TAGGING_MODE_UNTAGGED)

        self.vlan100_member1 = sai_thrift_create_vlan_member(
            self.client,
            vlan_id=self.vlan100,
            bridge_port_id=self.lag1_bp,
            vlan_tagging_mode=SAI_VLAN_TAGGING_MODE_UNTAGGED)

        sai_thrift_set_lag_attribute(self.client, self.lag_id, port_vlan_id=100)
        sai_thrift_set_lag_attribute(self.client, self.lag_id1, port_vlan_id=100)

        self.vlan100_rif = sai_thrift_create_router_interface(
            self.client,
            type=SAI_ROUTER_INTERFACE_TYPE_VLAN,
            virtual_router_id=self.default_vrf,
            vlan_id=self.vlan100)

        self.rif_id2 = sai_thrift_create_router_interface(
            self.client,
            type=SAI_ROUTER_INTERFACE_TYPE_PORT,
            virtual_router_id=self.default_vrf,
            port_id=self.port26)

        self.nhop1 = sai_thrift_create_next_hop(
            self.client,
            ip=sai_ipaddress(self.ip_addr2),
            router_interface_id=self.rif_id2,
            type=SAI_NEXT_HOP_TYPE_IP)
        self.neighbor_entry1 = sai_thrift_neighbor_entry_t(
            rif_id=self.rif_id2, ip_address=sai_ipaddress(self.ip_addr2))
        sai_thrift_create_neighbor_entry(
            self.client, self.neighbor_entry1, dst_mac_address=self.dst_mac)

        self.route_entry0 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf, destination=sai_ipprefix('10.0.0.1/24'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry0, next_hop_id=self.nhop1)

        self.route_entry1 = sai_thrift_route_entry_t(
            vr_id=self.default_vrf,
            destination=sai_ipprefix(
                '1234:5678:9abc:def0:4422:1133:5577:99aa/128'))
        sai_thrift_create_route_entry(
            self.client, self.route_entry1, next_hop_id=self.nhop1)

        #Set the num of ACL entries to be create
        self.table_entry_number = 512
        #create an ACL table group for ingress stage
        self.table_stage = SAI_ACL_STAGE_INGRESS
        self.table_bind_points = [SAI_ACL_BIND_POINT_TYPE_PORT,
                                  SAI_ACL_BIND_POINT_TYPE_SWITCH,
                                  SAI_ACL_BIND_POINT_TYPE_LAG]
        self.table_bind_point_type_list = sai_thrift_s32_list_t(
            count=len(self.table_bind_points), int32list=self.table_bind_points)
        self.group_type = SAI_ACL_TABLE_GROUP_TYPE_PARALLEL
        self.acl_table_group_Igr = sai_thrift_create_acl_table_group(self.client, self.table_stage, self.table_bind_point_type_list, self.group_type)
        assert(self.acl_table_group_Igr != SAI_NULL_OBJECT_ID)

        #Set the pri for table in the ingress acl group
        self.L3Igr_group_member_priority = 100
        self.MirrorV4_group_member_priority = 100
        self.MirrorV6_group_member_priority = 100
        self.L3V6Igr_group_member_priority = 100
        self.INT_group_member_priority = 100
        self.IsolateV4_group_member_priority = 100
        self.IsolateV6_group_member_priority = 100
        self.Aggstat_group_member_priority = 100

        #config packet action drop for action set in acl entries
        self.packet_action_drop = sai_thrift_acl_action_data_t(
            enable=True,
            parameter=sai_thrift_acl_action_parameter_t(
                s32=SAI_PACKET_ACTION_DROP))

