    def tearDown(self):
        '''
        Clean up resources after testing
        '''

        status = sai_thrift_set_lag_attribute(self.client,
                                              lag_oid=self.lag_id,
                                              ingress_acl=0)
        assert (status == SAI_STATUS_SUCCESS)

        #acl table group remove
        status = sai_thrift_remove_acl_table_group(self.client, self.acl_table_group_Igr)
        assert (status == SAI_STATUS_SUCCESS)

        sai_thrift_remove_route_entry(self.client, self.route_entry0)
        sai_thrift_remove_route_entry(self.client, self.route_entry1)
        sai_thrift_remove_neighbor_entry(self.client, self.neighbor_entry1)
        sai_thrift_remove_next_hop(self.client, self.nhop1)

        sai_thrift_set_lag_attribute(self.client, self.lag_id, port_vlan_id=1)
        sai_thrift_set_lag_attribute(self.client, self.lag_id1, port_vlan_id=1)

        sai_thrift_remove_router_interface(self.client, self.vlan100_rif)
        sai_thrift_remove_router_interface(self.client, self.rif_id2)

        sai_thrift_remove_vlan_member(self.client, self.vlan100_member0)
        sai_thrift_remove_vlan_member(self.client, self.vlan100_member1)
        sai_thrift_remove_vlan(self.client, self.vlan100)

        sai_thrift_remove_lag_member(self.client, self.lag_member_id1)
        sai_thrift_remove_lag_member(self.client, self.lag_member_id2)
        sai_thrift_remove_lag_member(self.client, self.lag_member_id3)
        sai_thrift_remove_lag_member(self.client, self.lag_member_id4)
        sai_thrift_remove_lag_member(self.client, self.lag_member_id5)
        sai_thrift_remove_lag_member(self.client, self.lag_member_id6)

        sai_thrift_remove_bridge_port(self.client, self.lag_bp)
        sai_thrift_remove_bridge_port(self.client, self.lag1_bp)
        sai_thrift_remove_lag(self.client, self.lag_id)
        sai_thrift_remove_lag(self.client, self.lag_id1)

        super(AclipprotocolipTypeTestIgr, self).tearDown()


    def testINTTableAclIgrAdd(self,field_dscp=False,field_ip_protocol=False,field_ecn=False,field_l4_dst_port=False,field_bth_reserved=False):
        '''
        Verify INT table ingress creation
        '''
        print("testINTTableAclIgrAdd")
        #Define the types of actions that the ACL table can perform
        self.INT_table_action_types = [SAI_ACL_ACTION_TYPE_SET_DLB_SPRAY_ENABLE,
                                       SAI_ACL_ACTION_TYPE_COUNTER,
                                       SAI_ACL_ACTION_TYPE_INT_INSERT,
                                       #SAI_ACL_ACTION_TYPE_INT_DELETE,
                                       SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                       SAI_ACL_ACTION_TYPE_TAM_INT_OBJECT,
                                       SAI_ACL_ACTION_TYPE_SET_TC,
                                       SAI_ACL_ACTION_TYPE_SET_DSCP]
        if get_platform() == 'clx':
            self.INT_table_action_types.remove(SAI_ACL_ACTION_TYPE_SET_DSCP)
        self.INT_table_acl_action_type_list = sai_thrift_s32_list_t(
            count=len(self.INT_table_action_types), int32list=self.INT_table_action_types)
        #Create ACL table for ingress traffic
        self.INT_acl_table = sai_thrift_create_acl_table(
            self.client,
            acl_stage=self.table_stage,
            acl_bind_point_type_list=self.table_bind_point_type_list,
            acl_action_type_list=self.INT_table_acl_action_type_list,
            size=self.table_entry_number,
            #field_ttl=True,
            field_in_ports=True,
            field_dscp=True,
            field_ecn=True,
            field_ip_protocol=True,
            field_acl_ip_type=True,
            field_l4_dst_port=True,
            field_outer_vlan_id=True,
            field_inner_bth_reserved=True,
            field_inner_l4_dst_port=True,
            field_inner_ip_protocol=True,
            field_src_ip=True,
            field_src_ipv6=True,
            field_bth_reserved=True)
        assert(self.INT_acl_table != SAI_NULL_OBJECT_ID)
        self.dst_ip_mask = '255.255.255.255'
        #Create INT_acl_table as ACL table group member
        self.INT_acl_table_group_member = sai_thrift_create_acl_table_group_member(
            self.client,
            self.acl_table_group_Igr,
            self.INT_acl_table,
            self.INT_group_member_priority)
        #Create ACL counter for ingress traffic
        self.INT_acl_counter_ingress = sai_thrift_create_acl_counter(
            self.client,
            table_id=self.INT_acl_table,
            enable_packet_count=True,
            enable_byte_count=True)
        #Prepare ACL action data for the ingress counter
        self.INT_action_counter_ingress = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=self.INT_acl_counter_ingress),
            enable=True)

        self.src_ipv6_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(ip6=self.ipv6_addr3),
            mask=sai_thrift_acl_field_data_mask_t(ip6=self.dst_ipv6_mask))

        self.dst_ipv4_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(ip4=self.ip_addr1),
            mask=sai_thrift_acl_field_data_mask_t(ip4=self.dst_ip_mask))

        ip_type = SAI_ACL_IP_TYPE_IP
        ip_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ip_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        ipv4_type = SAI_ACL_IP_TYPE_IPV4ANY
        ipv4_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ipv4_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        ipv6_type = SAI_ACL_IP_TYPE_IPV6ANY
        ipv6_type_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(s32=ipv6_type),
            mask=sai_thrift_acl_field_data_mask_t(s32=-1))

        self.ipv6_next_header_tcp = 6
        self.ipv6_next_header_udp = 17

        self.field_ip_protocol_tcp = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=self.ipv6_next_header_tcp),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_ip_protocol_udp = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=self.ipv6_next_header_udp),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_ecn_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=1),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        self.field_dscp_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=50),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        portlist1 = [self.port0]
        portobjlist1=sai_thrift_object_list_t(
            count=len(portlist1),
            idlist=portlist1)

        in_ports_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(objlist=portobjlist1),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))

        l4_dst_port_mask = 32759
        l4_dst_port_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u16=self.l4_dst_port),
            mask=sai_thrift_acl_field_data_mask_t(u16=l4_dst_port_mask))


        bth_reserved = ctypes.c_int8(0x0)
        bth_reserved_t = sai_thrift_acl_field_data_t(
            enable=True,
            data=sai_thrift_acl_field_data_data_t(u8=bth_reserved.value),
            mask=sai_thrift_acl_field_data_mask_t(u8=-1))


        if field_ip_protocol != False:
            self.INT_acl_entry = sai_thrift_create_acl_entry(
                self.client,
                table_id=self.INT_acl_table,
                priority=10,
                field_ip_protocol=self.field_ip_protocol_udp,
                action_counter=self.INT_action_counter_ingress)

        if field_dscp != False:
            self.INT_acl_entry = sai_thrift_create_acl_entry(
                self.client,
                table_id=self.INT_acl_table,
                priority=10,
                field_dscp=self.field_dscp_t,
                action_counter=self.INT_action_counter_ingress)

        if field_ecn != False:
            self.INT_acl_entry = sai_thrift_create_acl_entry(
                self.client,
                table_id=self.INT_acl_table,
                priority=10,
                field_ecn=self.field_ecn_t,
                action_counter=self.INT_action_counter_ingress)

        if field_l4_dst_port != False:
            self.INT_acl_entry = sai_thrift_create_acl_entry(
                self.client,
                table_id=self.INT_acl_table,
                priority=10,
                field_l4_dst_port=l4_dst_port_t,
                action_counter=self.INT_action_counter_ingress)

        if field_bth_reserved != False:
            self.INT_acl_entry = sai_thrift_create_acl_entry(
                self.client,
                table_id=self.INT_acl_table,
                priority=10,
                field_bth_reserved=bth_reserved_t,
                action_counter=self.INT_action_counter_ingress)

        # pdb.set_trace()
        send_packet(self, self.dev_port0, self.pkt1)
        send_packet(self, self.dev_port0, self.pkt2)
        send_packet(self, self.dev_port0, self.pkt3)
        send_packet(self, self.dev_port0, self.pkt4)
        send_packet(self,self.dev_port0,self.rocev2_reserved0)
        if field_ip_protocol != False:
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, self.INT_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 3)

        if field_dscp != False:
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, self.INT_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 5)

        if field_ecn != False:
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, self.INT_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 5)

        if field_l4_dst_port != False:
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, self.INT_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 4)

        if field_bth_reserved != False:
            # pdb.set_trace()
            packets = sai_thrift_get_acl_counter_attribute(
                self.client, self.INT_acl_counter_ingress, packets=True)
            self.assertEqual(packets['packets'], 1)



