    def testINTTableAclIgrRm(self):
        '''
        Verify INT table ingress destroy
        '''
        print("testINTTableAclIgrRm")
        self.action_counter_ingress_rm = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=0),
            enable=True)
        status = sai_thrift_remove_acl_table_group_member(self.client, self.INT_acl_table_group_member)
        assert (status == SAI_STATUS_SUCCESS)
        #remove ACL entry
        sai_thrift_set_acl_entry_attribute(
            self.client, self.INT_acl_entry,
            action_counter=self.action_counter_ingress_rm)
        status = sai_thrift_remove_acl_entry(self.client, self.INT_acl_entry)
        assert (status == SAI_STATUS_SUCCESS)

        #Set attr for the ACL counter to reset packet counts
        sai_thrift_set_acl_counter_attribute(
            self.client, self.INT_acl_counter_ingress, packets=0)
        packets = sai_thrift_get_acl_counter_attribute(
            self.client, self.INT_acl_counter_ingress, packets=True)
        self.assertEqual(packets['packets'], 0)
        #Remove ACL counter
        sai_thrift_remove_acl_counter(self.client, self.INT_acl_counter_ingress)
        #Remove INT ingress ACL table
        status = sai_thrift_remove_acl_table(self.client, self.INT_acl_table)
        assert (status == SAI_STATUS_SUCCESS)

    def testAggstatTableAclIgrRm(self):
        '''
        Verify Aggstat table ingress destroy
        '''
        print("testAggstatTableAclIgrRm")
        self.action_counter_ingress_rm = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=0),
            enable=True)
        status = sai_thrift_remove_acl_table_group_member(self.client, self.Aggstat_acl_table_group_member)
        assert (status == SAI_STATUS_SUCCESS)
        #remove ACL entry
        sai_thrift_set_acl_entry_attribute(
            self.client, self.Aggstat_acl_entry,
            action_counter=self.action_counter_ingress_rm)
        status = sai_thrift_remove_acl_entry(self.client, self.Aggstat_acl_entry)
        assert (status == SAI_STATUS_SUCCESS)

        #Remove Aggstat ingress ACL table
        status = sai_thrift_remove_acl_table(self.client, self.Aggstat_acl_table)
        assert (status == SAI_STATUS_SUCCESS)

