    def testAggstatTableAclEgrAdd(self):
        '''
        Verify  Aggregate_Stat table egress creation
        '''
        print("testAggstatTableAclEgrAdd")
        #Define the types of actions that the ACL table can perform
        self.AggstatEgr_table_action_types = [SAI_ACL_ACTION_TYPE_PACKET_ACTION,
                                              SAI_ACL_ACTION_TYPE_SET_DSCP,
                                              SAI_ACL_ACTION_TYPE_PER_PORT_COUNTER]
