    def testAggstatTableAclEgrRm(self):
        '''
        Verify Aggstat table egress destroy
        '''
        print("testAggstatTableAclEgrRm")
        self.action_counter_egress_rm = sai_thrift_acl_action_data_t(
            parameter=sai_thrift_acl_action_parameter_t(
                oid=0),
            enable=True)
        status = sai_thrift_remove_acl_table_group_member(self.client, self.AggstatEgr_acl_table_group_member)
        assert (status == SAI_STATUS_SUCCESS)
        #remove all ACL entries
        status = sai_thrift_remove_acl_entry(self.client, self.AggstatEgr_acl_entry)
        assert (status == SAI_STATUS_SUCCESS)
        status = sai_thrift_remove_acl_entry(self.client, self.AggstatEgr_acl_entry1)
        assert (status == SAI_STATUS_SUCCESS)
        status = sai_thrift_remove_acl_entry(self.client, self.AggstatEgr_acl_entry2)
        assert (status == SAI_STATUS_SUCCESS)

        #Remove AggstatEgr egress ACL table
        status = sai_thrift_remove_acl_table(self.client, self.AggstatEgr_acl_table)
        assert (status == SAI_STATUS_SUCCESS)
